/**
 * Tiny DOM helpers – the UI is vanilla TS, so this keeps element creation readable.
 */
import { UserError } from '../core/errors';

export type Child = Node | string | number | null | undefined | false;

type Handlers = { [K in keyof HTMLElementEventMap]?: (ev: HTMLElementEventMap[K]) => void };

interface Props {
  class?: string;
  text?: string;
  /** Raw HTML – ONLY for markup generated by our own code (icons). Never for user data. */
  html?: string;
  title?: string | undefined;
  /** Sets aria-label. */
  label?: string;
  attrs?: Record<string, string | number | boolean | null | undefined>;
  style?: string | undefined;
  on?: Handlers;
}

/** Create an element: h('button', { class: 'btn', on: { click } }, 'Text'). */
export function h<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  props: Props = {},
  ...children: Child[]
): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  if (props.class) el.className = props.class;
  if (props.html !== undefined) el.innerHTML = props.html;
  if (props.text !== undefined) el.textContent = props.text;
  if (props.title) el.title = props.title;
  if (props.label) el.setAttribute('aria-label', props.label);
  if (props.style) el.setAttribute('style', props.style);
  if (props.attrs) {
    for (const [k, v] of Object.entries(props.attrs)) {
      if (v === null || v === undefined || v === false) continue;
      el.setAttribute(k, v === true ? '' : String(v));
    }
  }
  if (props.on) {
    for (const [ev, fn] of Object.entries(props.on)) {
      if (fn) el.addEventListener(ev, fn as EventListener);
    }
  }
  append(el, ...children);
  return el;
}

export function append(parent: Node, ...children: Child[]): void {
  for (const c of children) {
    if (c === null || c === undefined || c === false) continue;
    parent.appendChild(typeof c === 'string' || typeof c === 'number' ? document.createTextNode(String(c)) : c);
  }
}

export function clear(el: Element): void {
  while (el.firstChild) el.removeChild(el.firstChild);
}

let uid = 0;
/** Unique DOM id (for label/for associations). */
export function nextId(prefix = 'cb'): string {
  uid += 1;
  return `${prefix}-${uid}`;
}

/** Wait for the next animation frame (falls back to a timeout when rAF is throttled). */
export function nextFrame(): Promise<void> {
  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      resolve();
    };
    requestAnimationFrame(finish);
    setTimeout(finish, 64);
  });
}

/**
 * Coalesce many calls into one per animation frame. Uses rAF with a timeout fallback because
 * rAF is paused in hidden windows (the work must still happen eventually).
 */
export function frameCoalescer(fn: () => void): { schedule(): void; flush(): void } {
  let queued = false;
  let raf = 0;
  let timer = 0;
  const run = () => {
    if (!queued) return;
    queued = false;
    cancelAnimationFrame(raf);
    clearTimeout(timer);
    fn();
  };
  return {
    schedule() {
      if (queued) return;
      queued = true;
      raf = requestAnimationFrame(run);
      timer = window.setTimeout(run, 120);
    },
    flush: run,
  };
}

/** Simple observable value. */
export class Signal<T> {
  private listeners = new Set<(v: T) => void>();
  constructor(private v: T) {}
  get value(): T {
    return this.v;
  }
  set(v: T): void {
    this.v = v;
    this.listeners.forEach((l) => {
      l(v);
    });
  }
  subscribe(fn: (v: T) => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
}

/**
 * What the interface says about an error: a UserError's own message; for anything else (a bug, a
 * failure of the web engine, a value that is not an Error) a general message with the raw text as
 * detail. Written to follow the title of an error toast.
 */
export function errorMessage(e: unknown): string {
  if (e instanceof UserError) return e.message;
  let raw: string;
  if (e instanceof Error) raw = e.message || e.name;
  else if (typeof e === 'string') raw = e;
  else {
    try {
      raw = JSON.stringify(e) ?? String(e);
    } catch {
      raw = String(e);
    }
  }
  const detail = raw.trim().replace(/\.+$/, '');
  return `Something unexpected went wrong${detail ? `: ${detail}` : ''}. If it keeps happening, report it at github.com/Infinitinker/Mockup-Director/issues.`;
}

export const isMac: boolean = /Mac|iPhone|iPad|iPod/i.test(
  (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ||
    navigator.platform ||
    navigator.userAgent,
);

/** Human-readable shortcut label: ⌘S on macOS, Ctrl+S elsewhere. */
export function shortcutLabel(key: string, shift = false): string {
  if (isMac) return `${shift ? '⇧' : ''}⌘${key}`;
  return `Ctrl+${shift ? 'Shift+' : ''}${key}`;
}

export function clamp(v: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, v));
}

/** True when keyboard focus is in a text-editing control. */
export function isTextEditing(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  if (target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement) return true;
  if (target instanceof HTMLInputElement) {
    return !['range', 'checkbox', 'radio', 'button', 'color', 'submit', 'reset'].includes(target.type);
  }
  return false;
}
